import React, { useState, useCallback } from 'react';
import { motion } from 'framer-motion';
import { useDropzone } from 'react-dropzone';
import {
  Upload,
  FileText,
  FileSpreadsheet,
  File,
  X,
  CheckCircle,
  AlertCircle,
  Loader,
  Zap,
  Target,
  Clock,
  Download,
  Eye,
  RefreshCw,
  FileQuestion,
  Database
} from 'lucide-react';
import toast from 'react-hot-toast';
import { apiService, ProcessResult, AnswerResult } from '../../services/api';

interface UploadedFile {
  id: string;
  file: File;
  status: 'uploading' | 'processing' | 'completed' | 'error' | 'answering' | 'ready_for_download';
  progress: number;
  type: 'rfp' | 'supporting';
  questions?: string[];
  questionsCount?: number;
  outputFilePath?: string;
  error?: string;
  isManuallyClassified?: boolean; // Track if user manually changed classification
}

const UploadCenter: React.FC = () => {
  const [uploadedFiles, setUploadedFiles] = useState<UploadedFile[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  const simulateUpload = useCallback(async (fileId: string, file: File) => {
    // Simulate upload progress
    const uploadInterval = setInterval(() => {
      setUploadedFiles((prev) =>
        prev.map((f) => {
          if (f.id === fileId) {
            const newProgress = Math.min(f.progress + Math.random() * 20 + 10, 100);
            return { ...f, progress: newProgress };
          }
          return f;
        })
      );
    }, 200);

    // Wait for upload completion
    await new Promise(resolve => setTimeout(resolve, 2000));
    clearInterval(uploadInterval);

    // Mark as uploaded and start processing
    setUploadedFiles((prev) =>
      prev.map((f) => {
        if (f.id === fileId) {
          return { ...f, progress: 100, status: 'processing' };
        }
        return f;
      })
    );

    // Process the file based on type
    if (file.name.toLowerCase().includes('rfp') || file.name.toLowerCase().includes('request')) {
      await processRFPFile(fileId, file);
    } else {
      await ingestSupportingDocument(fileId, file);
    }
  }, []);

  const processRFPFile = async (fileId: string, file: File) => {
    try {
      const result: ProcessResult = await apiService.processRFP(file);
      
      setUploadedFiles((prev) =>
        prev.map((f) => {
          if (f.id === fileId) {
            return {
              ...f,
              status: 'completed',
              questions: result.questions,
              questionsCount: result.count
            };
          }
          return f;
        })
      );
      
      toast.success(`RFP processed! ${result.count} questions extracted.`);
    } catch (error) {
      setUploadedFiles((prev) =>
        prev.map((f) => {
          if (f.id === fileId) {
            return {
              ...f,
              status: 'error',
              error: 'Failed to process RFP'
            };
          }
          return f;
        })
      );
      toast.error('Failed to process RFP document');
    }
  };

  const ingestSupportingDocument = async (fileId: string, file: File) => {
    try {
      await apiService.ingestDocuments([file]);
      
      setUploadedFiles((prev) =>
        prev.map((f) => {
          if (f.id === fileId) {
            return { ...f, status: 'completed' };
          }
          return f;
        })
      );
      
      toast.success('Supporting document ingested successfully!');
    } catch (error) {
      setUploadedFiles((prev) =>
        prev.map((f) => {
          if (f.id === fileId) {
            return {
              ...f,
              status: 'error',
              error: 'Failed to ingest document'
            };
          }
          return f;
        })
      );
      toast.error('Failed to ingest supporting document');
    }
  };

  const generateAnswers = async (fileId: string, file: File) => {
    setUploadedFiles((prev) =>
      prev.map((f) => {
        if (f.id === fileId) {
          return { ...f, status: 'answering' };
        }
        return f;
      })
    );

    try {
      const result: AnswerResult = await apiService.answerRFP(file);
      
      setUploadedFiles((prev) =>
        prev.map((f) => {
          if (f.id === fileId) {
            return {
              ...f,
              status: 'ready_for_download',
              outputFilePath: result.file_path
            };
          }
          return f;
        })
      );
      
      toast.success(`Answers generated! Document ready for download.`);
    } catch (error) {
      setUploadedFiles((prev) =>
        prev.map((f) => {
          if (f.id === fileId) {
            return {
              ...f,
              status: 'error',
              error: 'Failed to generate answers'
            };
          }
          return f;
        })
      );
      toast.error('Failed to generate answers');
    }
  };

  const onDrop = useCallback((acceptedFiles: File[]) => {
    const newFiles = acceptedFiles.map((file) => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      status: 'uploading' as const,
      progress: 0,
      type: (file.name.toLowerCase().includes('rfp') || file.name.toLowerCase().includes('request')) 
        ? 'rfp' as const 
        : 'supporting' as const,
    }));

    setUploadedFiles((prev) => [...prev, ...newFiles]);

    // Process each file
    newFiles.forEach((uploadFile) => {
      simulateUpload(uploadFile.id, uploadFile.file);
    });
  }, [simulateUpload]);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'],
      'application/vnd.ms-excel': ['.xls'],
      'application/pdf': ['.pdf'],
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document': ['.docx'],
      'application/msword': ['.doc']
    },
    multiple: true
  });

  const removeFile = (fileId: string) => {
    setUploadedFiles((prev) => prev.filter((file) => file.id !== fileId));
  };

  const getFileIcon = (filename: string) => {
    const ext = filename.toLowerCase().split('.').pop();
    switch (ext) {
      case 'xlsx':
      case 'xls':
        return <FileSpreadsheet className="h-8 w-8 text-green-500" />;
      case 'pdf':
        return <FileText className="h-8 w-8 text-red-500" />;
      case 'docx':
      case 'doc':
        return <FileText className="h-8 w-8 text-blue-500" />;
      default:
        return <File className="h-8 w-8 text-gray-500" />;
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'uploading':
        return <Loader className="h-5 w-5 text-blue-500 animate-spin" />;
      case 'processing':
        return <Zap className="h-5 w-5 text-yellow-500 animate-pulse" />;
      case 'answering':
        return <Target className="h-5 w-5 text-purple-500 animate-pulse" />;
      case 'completed':
        return <CheckCircle className="h-5 w-5 text-green-500" />;
      case 'ready_for_download':
        return <Download className="h-5 w-5 text-blue-600" />;
      case 'error':
        return <AlertCircle className="h-5 w-5 text-red-500" />;
      default:
        return null;
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case 'uploading':
        return 'Uploading...';
      case 'processing':
        return 'Extracting questions...';
      case 'answering':
        return 'Generating answers...';
      case 'completed':
        return 'Questions extracted';
      case 'ready_for_download':
        return 'Ready for download';
      case 'error':
        return 'Error occurred';
      default:
        return '';
    }
  };

  const startProcessing = async () => {
    setIsProcessing(true);
    const rfpFilesToProcess = rfpFiles.filter(file => file.status === 'completed');
    
    if (rfpFilesToProcess.length === 0) {
      toast.error('No RFP files ready for processing');
      setIsProcessing(false);
      return;
    }

    toast.success(`Starting answer generation for ${rfpFilesToProcess.length} RFP(s)...`);
    
    try {
      // Process each RFP file sequentially
      for (const rfpFile of rfpFilesToProcess) {
        await generateAnswers(rfpFile.id, rfpFile.file);
      }
      toast.success('All RFPs processed successfully!');
    } catch (error) {
      toast.error('Some RFPs failed to process');
    } finally {
      setIsProcessing(false);
    }
  };

  const rfpFiles = uploadedFiles.filter(file => file.type === 'rfp');
  const supportingFiles = uploadedFiles.filter(file => file.type === 'supporting');
  const completedRFPs = rfpFiles.filter(file => file.status === 'completed');
  const readyForDownload = rfpFiles.filter(file => file.status === 'ready_for_download');

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-gray-100">
            Upload Center
          </h1>
          <p className="text-gray-600 dark:text-gray-400 mt-2">
            Upload RFP documents and supporting materials for AI-powered processing
          </p>
        </div>
        
        {rfpFiles.length > 0 && completedRFPs.length > 0 && (
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={startProcessing}
            disabled={isProcessing}
            className="btn-primary px-6 py-3 text-lg font-semibold relative overflow-hidden"
          >
            {isProcessing ? (
              <div className="flex items-center">
                <Loader className="h-5 w-5 mr-2 animate-spin" />
                Generating Answers...
              </div>
            ) : (
              <div className="flex items-center">
                <Target className="h-5 w-5 mr-2" />
                Generate Answers ({completedRFPs.length})
              </div>
            )}
          </motion.button>
        )}
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="card"
        >
          <div className="flex items-center">
            <div className="p-3 bg-blue-100 dark:bg-blue-900/30 rounded-lg">
              <FileSpreadsheet className="h-6 w-6 text-blue-600 dark:text-blue-400" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-gray-600 dark:text-gray-400">RFP Documents</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-gray-100">{rfpFiles.length}</p>
            </div>
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
          className="card"
        >
          <div className="flex items-center">
            <div className="p-3 bg-green-100 dark:bg-green-900/30 rounded-lg">
              <File className="h-6 w-6 text-green-600 dark:text-green-400" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-gray-600 dark:text-gray-400">Supporting Docs</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-gray-100">{supportingFiles.length}</p>
            </div>
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="card"
        >
          <div className="flex items-center">
            <div className="p-3 bg-purple-100 dark:bg-purple-900/30 rounded-lg">
              <CheckCircle className="h-6 w-6 text-purple-600 dark:text-purple-400" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-gray-600 dark:text-gray-400">Processed</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-gray-100">{completedRFPs.length}</p>
            </div>
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="card"
        >
          <div className="flex items-center">
            <div className="p-3 bg-yellow-100 dark:bg-yellow-900/30 rounded-lg">
              <Target className="h-6 w-6 text-yellow-600 dark:text-yellow-400" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-gray-600 dark:text-gray-400">Questions</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-gray-100">
                {completedRFPs.reduce((acc, file) => acc + (file.questionsCount || 0), 0)}
              </p>
            </div>
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.4 }}
          className="card"
        >
          <div className="flex items-center">
            <div className="p-3 bg-green-100 dark:bg-green-900/30 rounded-lg">
              <Download className="h-6 w-6 text-green-600 dark:text-green-400" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-gray-600 dark:text-gray-400">Ready</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-gray-100">{readyForDownload.length}</p>
            </div>
          </div>
        </motion.div>
      </div>

      {/* Upload Area */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.4 }}
        className="card"
      >
        <div
          {...getRootProps()}
          className={`border-2 border-dashed rounded-xl p-12 text-center cursor-pointer transition-all duration-300 ${
            isDragActive
              ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20'
              : 'border-gray-300 dark:border-gray-600 hover:border-primary-400 hover:bg-gray-50 dark:hover:bg-gray-700/50'
          }`}
        >
          <input {...getInputProps()} />
          <div className="space-y-4">
            <motion.div
              animate={isDragActive ? { scale: 1.1 } : { scale: 1 }}
              className="w-16 h-16 bg-gradient-to-r from-blue-600 to-purple-600 rounded-2xl flex items-center justify-center mx-auto"
            >
              <Upload className="h-8 w-8 text-white" />
            </motion.div>
            <div>
              <h3 className="text-xl font-semibold text-gray-900 dark:text-gray-100 mb-2">
                {isDragActive ? 'Drop files here' : 'Upload your documents'}
              </h3>
              <p className="text-gray-600 dark:text-gray-400 mb-4">
                Drag and drop your RFP and supporting documents, or click to browse
              </p>
              <div className="flex flex-wrap justify-center gap-2 text-sm text-gray-500 dark:text-gray-400">
                <span className="px-2 py-1 bg-gray-100 dark:bg-gray-700 rounded">.xlsx</span>
                <span className="px-2 py-1 bg-gray-100 dark:bg-gray-700 rounded">.pdf</span>
                <span className="px-2 py-1 bg-gray-100 dark:bg-gray-700 rounded">.docx</span>
                <span className="px-2 py-1 bg-gray-100 dark:bg-gray-700 rounded">.doc</span>
              </div>
            </div>
          </div>
        </div>
      </motion.div>

      {/* File List */}
      {uploadedFiles.length > 0 && (
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.5 }}
          className="card"
        >
          <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-6">
            Uploaded Files ({uploadedFiles.length})
          </h3>
          <div className="space-y-4">
            {uploadedFiles.map((uploadFile) => (
              <div
                key={uploadFile.id}
                className="flex items-center p-4 bg-gray-50 dark:bg-gray-700/50 rounded-lg border border-gray-200 dark:border-gray-600"
              >
                <div className="flex-shrink-0">
                  {getFileIcon(uploadFile.file.name)}
                </div>
                <div className="flex-1 min-w-0 ml-4">
                  <div className="flex items-center justify-between mb-2">
                    <p className="text-sm font-medium text-gray-900 dark:text-gray-100 truncate">
                      {uploadFile.file.name}
                    </p>
                    <div className="flex items-center space-x-2">
                      <span className={`px-2 py-1 text-xs font-medium rounded-full ${
                        uploadFile.type === 'rfp'
                          ? 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300'
                          : 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300'
                      }`}>
                        {uploadFile.type === 'rfp' ? 'RFP Document' : 'Supporting'}
                      </span>
                      {getStatusIcon(uploadFile.status)}
                    </div>
                  </div>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-4 text-sm text-gray-500 dark:text-gray-400">
                      <span>{(uploadFile.file.size / 1024 / 1024).toFixed(2)} MB</span>
                      {uploadFile.status === 'completed' && uploadFile.questionsCount && (
                        <span className="flex items-center">
                          <Target className="h-4 w-4 mr-1" />
                          {uploadFile.questionsCount} questions
                        </span>
                      )}
                      {(uploadFile.status === 'processing' || uploadFile.status === 'answering') && (
                        <span className="flex items-center text-yellow-600 dark:text-yellow-400">
                          <Clock className="h-4 w-4 mr-1" />
                          {getStatusText(uploadFile.status)}
                        </span>
                      )}
                      {uploadFile.status === 'ready_for_download' && uploadFile.outputFilePath && (
                        <span className="flex items-center text-green-600 dark:text-green-400">
                          <CheckCircle className="h-4 w-4 mr-1" />
                          Ready for download
                        </span>
                      )}
                      {uploadFile.status === 'error' && uploadFile.error && (
                        <span className="flex items-center text-red-600 dark:text-red-400">
                          <AlertCircle className="h-4 w-4 mr-1" />
                          {uploadFile.error}
                        </span>
                      )}
                    </div>
                    <div className="flex items-center space-x-2">
                      {uploadFile.status === 'completed' && uploadFile.type === 'rfp' && uploadFile.questions && (
                        <button
                          onClick={() => {
                            // Show questions modal or expand view
                            toast.success(`Found ${uploadFile.questionsCount} questions in this RFP`);
                          }}
                          className="p-2 text-blue-500 hover:text-blue-700 transition-colors rounded-lg hover:bg-blue-50 dark:hover:bg-blue-900/30"
                          title="View extracted questions"
                        >
                          <Eye className="h-4 w-4" />
                        </button>
                      )}
                      {uploadFile.status === 'ready_for_download' && uploadFile.outputFilePath && (
                        <a
                          href={apiService.getDownloadUrl(uploadFile.outputFilePath)}
                          download
                          className="p-2 text-green-500 hover:text-green-700 transition-colors rounded-lg hover:bg-green-50 dark:hover:bg-green-900/30"
                          title="Download completed RFP"
                        >
                          <Download className="h-4 w-4" />
                        </a>
                      )}
                      <button
                        onClick={() => removeFile(uploadFile.id)}
                        className="p-1 text-gray-400 hover:text-red-500 transition-colors"
                      >
                        <X className="h-4 w-4" />
                      </button>
                    </div>
                  </div>
                  {uploadFile.status === 'uploading' && (
                    <div className="mt-2">
                      <div className="bg-gray-200 dark:bg-gray-600 rounded-full h-2">
                        <motion.div
                          initial={{ width: 0 }}
                          animate={{ width: `${uploadFile.progress}%` }}
                          className="bg-gradient-to-r from-blue-600 to-purple-600 h-2 rounded-full"
                        />
                      </div>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </motion.div>
      )}
    </div>
  );
};

export default UploadCenter;
